// Dos triggers posibles (GET de verificación / POST de eventos): Config ya mezcló
// sus campos hacia aquí (includeOtherFields), así que basta con $json.
const cfg = $json;
const q = cfg.query || {};
const headers = cfg.headers || {};

// --- 1) Verificación del webhook (GET de Meta) ---
if (q['hub.mode'] || q['hub.challenge']) {
  const ok = q['hub.verify_token'] === cfg.verify_token;
  return [{ json: { tipo: ok ? 'verificacion' : 'ignorar',
    challenge: ok ? String(q['hub.challenge'] ?? '') : '',
    motivo: ok ? null : 'verify_token no coincide' } }];
}

// --- 2) Cuerpo: con rawBody llega como string; si no, ya viene parseado ---
let raw = null, body = null;
if (typeof cfg.body === 'string') { raw = cfg.body; try { body = JSON.parse(raw); } catch (e) { body = null; } }
else { body = cfg.body || null; }
if (!body) return [{ json: { tipo: 'ignorar', motivo: 'cuerpo no parseable' } }];

// --- 3) Firma X-Hub-Signature-256 (solo comprobable con el cuerpo crudo) ---
let firma = 'no_comprobada';
const sigHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';
if (raw && cfg.app_secret && !String(cfg.app_secret).startsWith('REPLACE_')) {
  const crypto = require('crypto');
  const esperado = 'sha256=' + crypto.createHmac('sha256', cfg.app_secret).update(raw, 'utf8').digest('hex');
  firma = (sigHeader && sigHeader === esperado) ? 'valida' : 'invalida';
}
// El veredicto viaja en la SALIDA del nodo, no solo en un console.log: los Code
// nodes corren en un task runner aparte y su log puede no llegar a `docker logs`,
// así que la firma era invisible por los dos caminos. Ahora se ve en la ejecución.
console.log('[whatsapp] firma=' + firma + ' (raw=' + (raw ? 'si' : 'no') + ')');
if (cfg.require_signature === true && firma !== 'valida') {
  return [{ json: { tipo: 'ignorar', motivo: 'firma ' + firma, firma } }];
}

// --- 4) Normalizar el payload de Meta ---
const value = body?.entry?.[0]?.changes?.[0]?.value || {};
const msg = value?.messages?.[0];
// Los avisos de estado (sent/delivered/read) llegan al mismo webhook: se ignoran.
if (!msg) return [{ json: { tipo: 'ignorar', motivo: value.statuses ? 'status' : 'sin mensajes', firma } }];

const pnid = value?.metadata?.phone_number_id || null;
if (pnid && cfg.phone_number_id && !String(cfg.phone_number_id).startsWith('REPLACE_')
    && pnid !== cfg.phone_number_id) {
  return [{ json: { tipo: 'ignorar', motivo: 'phone_number_id ajeno: ' + pnid, firma } }];
}

const from = msg.from || null;                       // E.164 sin '+'
const perfil = value?.contacts?.[0]?.profile?.name || null;
const texto = msg.type === 'text' ? (msg.text?.body || '') : '';

return [{ json: {
  tipo: msg.type === 'text' ? 'mensaje' : 'no_texto',
  firma,
  wamid: msg.id || null,
  from,
  entry: {
    canal: 'whatsapp',
    session_key: 'whatsapp:' + from,
    message: texto,
    from: { phone: from ? '+' + from : null, name: perfil },
    tenant: cfg.tenant || '__TENANT_ID__',
    reply_to: { phone_number_id: cfg.phone_number_id },
    client_message_id: msg.id || null,
  },
} }];

const e = $json ?? {};
const cfg = $('Config (editar por tenant)').item.json;
const norm = $('Code · Clasificar y normalizar').item.json;
const base_url = `https://graph.facebook.com/${cfg.graph_version || 'v21.0'}/${cfg.phone_number_id}/messages`;
const items = [];

// WhatsApp NO entiende markdown estándar: su negrita es *así* (un asterisco), la cursiva
// _así_ y el tachado ~así~. Un **negrita** del agente se ve con los asteriscos puestos, y
// las cabeceras ## salen tal cual. Se normaliza aquí, en el adapter, porque cada canal
// tiene su dialecto: el Core produce UN texto y cada canal lo adapta a lo suyo.
const aWhatsApp = (t) => (t || '').toString()
  .replace(/`{3}([\s\S]*?)`{3}/g, '$1')            // bloques de código: fuera
  .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')            // ## Título  -> *Título*
  .replace(/\*\*\*(.+?)\*\*\*/g, '*$1*')           // ***x***    -> *x*
  .replace(/\*\*(.+?)\*\*/g, '*$1*')               // **x**      -> *x*
  .replace(/__(.+?)__/g, '_$1_')                   // __x__      -> _x_
  .replace(/`(.+?)`/g, '$1')                       // `x`        -> x
  .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g, '$1: $2')  // [texto](url) -> texto: url
  .replace(/^[ \t]*[*+][ \t]+/gm, '- ')            // viñetas * o + -> -
  .trim();

// Aviso de privacidad como botón CTA-URL: WhatsApp no permite enlaces con texto
// personalizado en un mensaje de texto normal, así que va como mensaje interactivo
// aparte (tocar el botón solo abre la URL, no genera respuesta que haya que procesar).
// Límite real de WhatsApp: display_text del botón <= 20 caracteres.
if (e.privacy_prompt && e.privacy_prompt.url) {
  items.push({ json: {
    _url: base_url,
    _body: {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: norm.from,
      type: 'interactive',
      interactive: {
        type: 'cta_url',
        body: { text: (e.privacy_prompt.intro || '').slice(0, 1024) },
        action: {
          name: 'cta_url',
          parameters: {
            display_text: (e.privacy_prompt.label || 'Ver política').slice(0, 20),
            url: e.privacy_prompt.url,
          },
        },
      },
    },
  } });
}

// El resto de la respuesta (si lo hay) va como texto normal, sin repetir el aviso.
const texto = aWhatsApp(e.core_reply ?? e.reply ?? '');
if (texto) {
  items.push({ json: {
    _url: base_url,
    _body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: norm.from,
             type: 'text', text: { preview_url: false, body: texto } },
  } });
}

return items;

// Puede haber 1 o 2 respuestas (botón de privacidad + texto): se comprueban todas,
// no solo la primera, para no perder un fallo en el segundo envío.
const items = $input.all();
return items.map(item => {
  const r = item.json ?? {};
  const code = r.statusCode ?? 0;
  const body = (r.body ?? r) || {};
  if (code >= 300 || body.error) {
    throw new Error('WhatsApp send devolvió ' + code + ': ' + JSON.stringify(body.error || body));
  }
  return { json: { enviado: true, wamid: (body.messages && body.messages[0] && body.messages[0].id) || null } };
});

const cfg = $('Config (editar por tenant)').item.json;
const norm = $json ?? {};
return [{ json: {
  _url: `https://graph.facebook.com/${cfg.graph_version || 'v21.0'}/${cfg.phone_number_id}/messages`,
  _body: { messaging_product: 'whatsapp', recipient_type: 'individual',
           to: norm.from, type: 'text',
           text: { preview_url: false,
                   body: 'De momento solo puedo leer mensajes de texto. ¿Me lo escribes?' } },
} }];
